mapper.select:
SELECT event_id, title, event_type, sigungu, place_name, lat, lng, start_date, end_date, apply_start, apply_end, target, distances, fee_text, contact, homepage_url, status, source, source_url, collected_at FROM events
WHERE status = #{status}
ORDER BY CASE status WHEN 'PENDING' THEN 0 WHEN 'PUBLISHED' THEN 1 ELSE 2 END, collected_at DESC

mapper.update:
UPDATE events
title = #{title}, event_type = #{eventType}, sigungu = #{sigungu}, place_name = #{placeName}, lat = #{lat}, lng = #{lng}, start_date = #{startDate}, end_date = #{endDate}, apply_start = #{applyStart}, apply_end = #{applyEnd}, target = #{target}, distances = #{distances}, fee_text = #{feeText}, contact = #{contact}, homepage_url = #{homepageUrl}, source_url = #{sourceUrl},
WHERE event_id = #{eventId}
